package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen2Test {

    private static final double EPSILON = 1e-10;













    @Test
    public void testDivide_Branch_c_abs_less_than_d_abs() {
        // Path: FastMath.abs(c) < FastMath.abs(d)
        // c = 1.0, d = 2.0
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(1.0, 2.0);

        // Expected: (1+i) / (1+2i)
        // (1+i)(1-2i) / (1^2 + 2^2) = (1 - 2i + i - 2i^2) / 5 = (1 - i + 2) / 5 = (3 - i) / 5 = 0.6 - 0.2i
        Complex expected = new Complex(0.6, -0.2);
        Complex result = c.divide(divisor);

        assertEquals(expected.getReal(), result.getReal(), EPSILON);
        assertEquals(expected.getImaginary(), result.getImaginary(), EPSILON);
    }




}

package org.apache.commons.math.complex;

import java.io.*;
