import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen2Test {

    private static final double EPSILON = 1e-10;















    @Test
    public void testDivide_Branch_c_abs_greater_than_or_equal_d_abs() {
        // Path: FastMath.abs(c) >= FastMath.abs(d)
        // c = 2.0, d = 1.0
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(2.0, 1.0);

        // Expected: (1+i) / (2+i)
        // (1+i)(2-i) / (2^2 + 1^2) = (2 - i + 2i - i^2) / 5 = (2 + i + 1) / 5 = (3 + i) / 5 = 0.6 + 0.2i
        Complex expected = new Complex(0.6, 0.2);
        Complex result = c.divide(divisor);

        assertEquals(expected.getReal(), result.getReal(), EPSILON);
        assertEquals(expected.getImaginary(), result.getImaginary(), EPSILON);
    }


}

package org.apache.commons.math.complex;

import java.io.*;
