import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen2Test {

    private static final double EPSILON = 1e-10;

















    @Test
    public void testDivide_EqualAbsValues() {
        // Tests the 'else' branch when abs(c) == abs(d)
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(1.0, -1.0);

        // (1+i) / (1-i) = (1+i)(1+i) / 2 = (1 + 2i - 1) / 2 = i
        Complex expected = new Complex(0.0, 1.0);
        Complex result = c.divide(divisor);

        assertEquals(expected.getReal(), result.getReal(), EPSILON);
        assertEquals(expected.getImaginary(), result.getImaginary(), EPSILON);
    }
}
